  font-weight: 500;
}

.drive-page .components-button.is-link:hover,
.drive-page .components-button.is-link:focus-visible {
  transform: none;
  box-shadow: none;
}

.drive-page .components-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.28);
}

.drive-page .components-button:hover:not(:disabled),
.drive-page .components-button:focus-visible {
  transform: translateY(-1px);
}

.drive-page .components-button:disabled {
  opacity: 0.6;
  box-shadow: none;
  transform: none;
}

.sui-box-body .components-base-control {
  min-width: 100%;
}
.sui-box-body .components-base-control input[type=text] {
  min-width: 100%;
}
.sui-box-body .components-base-control label {
  display: block;
}

.drive-loading {
  text-align: center;
  padding: 40px 20px;
}
.drive-loading .components-spinner {
  margin: 0 auto 10px;
}
.drive-loading p {
  color: #8c8f94;
  margin: 0;
}

.drive-files-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.drive-file-card {
  display: flex;
  flex-direction: column;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 15px 35px rgba(15, 23, 42, 0.08);
  overflow: visible;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
}

.drive-file-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 45px rgba(15, 23, 42, 0.14);
}

.drive-file-card__preview {
  position: relative;
  height: 180px;
  background: linear-gradient(135deg, rgba(226, 232, 240, 0.8), rgba(241, 245, 249, 0.6));
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.drive-file-card__preview img {
  width: 100%;
  height: 100%;
  -o-object-fit: cover;
     object-fit: cover;
  border-radius: 12px 12px 0 0;
}

.drive-file-card__preview--folder {
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.15), rgba(29, 78, 216, 0.3));
}

.drive-file-card__preview-fallback {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  background: rgba(248, 250, 252, 0.9);
  border-radius: 12px 12px 0 0;
}

.drive-file-card__vector {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.drive-file-card__vector svg {
  width: 68px;
  height: auto;
  max-width: 80%;
}

.drive-file-card__vector--folder {
  color: #2563eb;
}

.drive-file-card__vector--file {
  flex-direction: column;
  gap: 6px;
  align-items: center;
  color: #1d4ed8;
}

.drive-file-card__file-ext {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #334155;
  pointer-events: none;
}

.drive-file-card__badge {
  position: absolute;
  top: 14px;
  left: 14px;
  background: rgba(15, 23, 42, 0.75);
  color: #fff;
  font-size: 12px;
  padding: 6px 10px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.drive-file-card__menu-trigger {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: rgba(15, 23, 42, 0.65);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  cursor: pointer;
  transition: background 0.2s ease, transform 0.2s ease;
}

.drive-file-card__menu-trigger span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #ffffff;
}

.drive-file-card__menu-trigger:hover {
  background: rgba(15, 23, 42, 0.85);
  transform: translateY(-1px);
}

.drive-file-card__menu-trigger:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.35);
}

.drive-file-card__menu {
  position: absolute;
  top: 46px;
  right: 16px;
  background: #ffffff;
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 10px;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.18);
  padding: 6px 0;
  min-width: 180px;
  display: flex;
  flex-direction: column;
  z-index: 3;
}

.drive-file-card__menu-item {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 9px 16px;
  background: transparent;
  border: none;
  font-size: 13px;
  color: #0f172a;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.drive-file-card__menu-item:hover,
.drive-file-card__menu-item:focus-visible {
  background: rgba(37, 99, 235, 0.12);
  color: #1d4ed8;
  outline: none;
}

.drive-file-card__menu-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.drive-file-card__menu-item--danger {
  color: #b91c1c;
}

.drive-file-card__menu-item--danger:hover,
.drive-file-card__menu-item--danger:focus-visible {
  background: rgba(248, 113, 113, 0.15);
  color: #991b1b;
}

.drive-file-card__meta {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
}

.drive-file-card__name {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  color: #0f172a;
  word-break: break-word;
}

.drive-file-card__details {
  margin: 0;
  font-size: 13px;
  color: #64748b;
}

.drive-file-card__rename {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.drive-file-card__rename-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sui-description {
  color: #757575;
  margin-bottom: 30px;
}

.components-notice {
  margin: 20px 0;
}
.components-notice.is-success {
  border-left-color: #00a32a;
}
.components-notice.is-error {
  border-left-color: #d63638;
}

@media (max-width: 768px) {
  .drive-page__header {
    flex-direction: column;
    align-items: flex-start;
  }
  .drive-page__header-status {
    max-width: none;
  }
  .drive-files-toolbar {
    flex-direction: column;
    align-items: stretch;
    gap: 16px;
  }
  .drive-files-toolbar__actions {
    width: 100%;
    justify-content: flex-start;
    margin-left: 0;
    gap: 10px;
  }
  .drive-files-toolbar__search {
    width: 100%;
    flex-wrap: wrap;
  }
  .drive-files-toolbar__search .components-base-control {
    min-width: 100%;
  }
  .drive-files-toolbar__sort,
  .drive-files-toolbar__sort .components-select-control__input {
    min-width: 100%;
  }
  .drive-files-toolbar__sort {
    flex: 1 1 100%;
  }
  .drive-upload-dropzone {
    padding: 24px 20px;
  }
  .drive-upload-dropzone__inner {
    min-height: 150px;
  }
  .drive-files-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .sui-box-header .sui-actions-right {
    margin-top: 15px;
  }
