variable collisions).\n@use \"~@wpmudev/shared-ui/scss/shared-ui\" as sui with (\n  $sui-font-path: \"~@wpmudev/shared-ui/dist/fonts/\",\n  $sui-image-path: \"~@wpmudev/shared-ui/dist/images/\"\n);\n\n// If you need variables/mixins from shared-ui, prefix with `sui.`\n// Example:\n// .btn { @include sui.button(); }\n// .title { font-family: sui.$sui-font-family; }\n\n// ------------------------------------------------------------\n// Local styles\n// ------------------------------------------------------------\n\n.drive-page {\n  display: flex;\n  flex-direction: column;\n  gap: 24px;\n}\n\n.drive-page__header {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 24px;\n  padding: 24px;\n  background: #ffffff;\n  border: 1px solid #dfe1e5;\n  border-radius: 12px;\n  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.08);\n}\n\n.drive-page__header-text .sui-header-title {\n  margin-bottom: 8px;\n}\n\n.drive-page__header-status {\n  max-width: 320px;\n}\n\n.drive-page__status-title {\n  margin: 12px 0 4px;\n  font-size: 16px;\n  font-weight: 600;\n  color: #1e293b;\n}\n\n.drive-page__status-text {\n  margin: 0;\n  color: #475569;\n  line-height: 1.4;\n}\n\n.drive-status-badge {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 4px 12px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.03em;\n  text-transform: uppercase;\n}\n\n.drive-status-badge--success {\n  color: #035d27;\n  background: rgba(0, 163, 42, 0.12);\n}\n\n.drive-status-badge--warning {\n  color: #8a5300;\n  background: rgba(218, 143, 0, 0.18);\n}\n\n.drive-status-badge--muted,\n.drive-status-badge--neutral {\n  color: #334155;\n  background: rgba(148, 163, 184, 0.22);\n}\n\n.drive-page__summary {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));\n  gap: 16px;\n}\n\n.drive-summary-card {\n  padding: 16px 18px;\n  border: 1px solid #e2e8f0;\n  border-radius: 10px;\n  background: #ffffff;\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.drive-summary-card__label {\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: #64748b;\n}\n\n.drive-summary-card__value {\n  font-size: 18px;\n  color: #0f172a;\n  font-weight: 600;\n}\n\n.drive-summary-card__helper {\n  margin: 0;\n  font-size: 13px;\n  color: #475569;\n  line-height: 1.4;\n}\n\n.drive-summary-card--success {\n  border-color: rgba(0, 163, 42, 0.25);\n}\n\n.drive-summary-card--warning {\n  border-color: rgba(218, 143, 0, 0.35);\n}\n\n.drive-summary-card--muted,\n.drive-summary-card--neutral {\n  border-color: rgba(148, 163, 184, 0.35);\n}\n\n.drive-page__grid {\n  display: grid;\n  gap: 24px;\n}\n\n.drive-page__grid--primary {\n  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\n}\n\n.drive-page__grid--actions {\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n}\n\n.drive-upload-dropzone {\n  position: relative;\n  border: 2px dashed #bfdbfe;\n  border-radius: 16px;\n  padding: 32px 24px;\n  background: linear-gradient(135deg, rgba(59, 130, 246, 0.08), rgba(37, 99, 235, 0.08));\n  text-align: center;\n  cursor: pointer;\n  transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;\n  width: 100%;\n}\n\n.drive-upload-dropzone:hover {\n  border-color: #2563eb;\n  background: rgba(59, 130, 246, 0.12);\n}\n\n.drive-upload-dropzone.is-dragging {\n  border-color: #2563eb;\n  background: rgba(37, 99, 235, 0.12);\n  box-shadow: 0 14px 32px rgba(37, 99, 235, 0.25);\n}\n\n.drive-upload-dropzone.has-file {\n  border-color: rgba(2, 132, 199, 0.5);\n  background: rgba(226, 232, 240, 0.35);\n}\n\n.drive-upload-dropzone:focus-visible {\n  outline: none;\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.25);\n}\n\n.drive-upload-dropzone__inner {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  min-height: 170px;\n  gap: 10px;\n}\n\n.drive-upload-dropzone__icon {\n  width: 60px;\n  height: 60px;\n  border-radius: 18px;\n  background: linear-gradient(135deg, #2563eb, #1d4ed8);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: #fff;\n  font-size: 28px;\n  box-shadow: 0 12px 28px rgba(29, 78, 216, 0.22);\n}\n\n.drive-upload-dropzone__icon::before {\n  content: '⬆';\n  transform: translateY(-1px);\n}\n\n.drive-upload-dropzone__title {\n  margin: 10px 0 0;\n  font-weight: 600;\n  color: #0f172a;\n}\n\n.drive-upload-dropzone__subtitle {\n  margin: 0;\n  color: #475569;\n}\n\n.drive-upload-dropzone__hint {\n  margin: 0;\n  font-size: 12px;\n  color: #64748b;\n}\n\n.drive-upload-dropzone__meta {\n  margin-top: 12px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 6px;\n}\n\n.drive-upload-dropzone__meta p {\n  margin: 0;\n  font-size: 13px;\n  color: #0f172a;\n}\n\n.drive-upload-dropzone__meta .components-button {\n  font-size: 12px;\n  padding: 0;\n  color: #1d4ed8;\n}\n\n.drive-upload-dropzone__meta .components-button:hover,\n.drive-upload-dropzone__meta .components-button:focus-visible {\n  color: #1e40af;\n  outline: none;\n}\n\n.drive-upload-dropzone__progress {\n  margin-top: 14px;\n  font-size: 13px;\n  font-weight: 600;\n  color: #1d4ed8;\n}\n\n.drive-file-input-native {\n  display: none;\n}\n\n.drive-browser {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.drive-files-toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.drive-breadcrumbs {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.drive-breadcrumbs__item {\n  border: 1px solid rgba(37, 99, 235, 0.28);\n  background: rgba(37, 99, 235, 0.08);\n  color: #1d4ed8;\n  border-radius: 999px;\n  padding: 6px 14px;\n  font-size: 13px;\n  cursor: pointer;\n  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;\n}\n\n.drive-breadcrumbs__item:hover:not(.is-current),\n.drive-breadcrumbs__item:focus-visible:not(.is-current) {\n  background: #1d4ed8;\n  color: #fff;\n  border-color: #1d4ed8;\n  outline: none;\n}\n\n.drive-breadcrumbs__item.is-current {\n  background: rgba(15, 23, 42, 0.08);\n  border-color: rgba(15, 23, 42, 0.1);\n  color: #0f172a;\n  cursor: default;\n}\n\n.drive-files-toolbar__actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n  margin-left: auto;\n}\n\n.drive-files-toolbar__sort {\n  min-width: 180px;\n  flex: 0 0 180px;\n}\n\n.drive-files-toolbar__sort .components-base-control {\n  margin: 0;\n}\n\n.drive-files-toolbar__sort .components-select-control__input {\n  min-width: 180px;\n}\n\n.drive-files-toolbar__search {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  row-gap: 10px;\n}\n\n.drive-files-toolbar__search .components-base-control {\n  min-width: 220px;\n  margin: 0;\n  flex: 1 1 220px;\n}\n\n.drive-files-toolbar__search .components-button {\n  flex-shrink: 0;\n}\n\n.drive-files-toolbar__clear {\n  padding: 0;\n  color: #334155;\n}\n\n.drive-card {\n  display: flex;\n  flex-direction: column;\n}\n\n.drive-card .sui-box-body {\n  flex: 1;\n}\n\n.drive-card__description {\n  margin: 0 0 16px;\n  color: #475569;\n  line-height: 1.5;\n}\n\n.drive-steps {\n  margin: 0 0 18px;\n  padding-left: 18px;\n  color: #334155;\n  line-height: 1.6;\n}\n\n.drive-info-block {\n  padding: 14px 16px;\n  background: #f8fafc;\n  border: 1px solid #e2e8f0;\n  border-radius: 8px;\n  margin-bottom: 12px;\n}\n\n.drive-info-block:last-child {\n  margin-bottom: 0;\n}\n\n.drive-info-block__label {\n  display: block;\n  font-weight: 600;\n  color: #1e293b;\n  margin-bottom: 6px;\n}\n\n.drive-info-block__code {\n  display: block;\n  word-break: break-all;\n  font-size: 13px;\n  background: rgba(15, 23, 42, 0.06);\n  padding: 6px 8px;\n  border-radius: 6px;\n}\n\n.drive-info-block__list {\n  margin: 0;\n  padding-left: 18px;\n  color: #475569;\n  font-size: 13px;\n  line-height: 1.5;\n}\n\n.drive-empty-state {\n  padding: 36px 20px;\n  text-align: center;\n  border: 1px dashed #cbd5f5;\n  border-radius: 10px;\n  background: rgba(59, 130, 246, 0.05);\n}\n\n.drive-empty-state__title {\n  margin: 0 0 8px;\n  font-weight: 600;\n  color: #1d4ed8;\n}\n\n.drive-empty-state__helper {\n  margin: 0;\n  color: #475569;\n}\n\n.drive-files-more {\n  margin-top: 20px;\n  text-align: center;\n}\n\n.drive-card--files .drive-card__description {\n  margin-bottom: 24px;\n}\n\n.drive-page .components-button {\n  border-radius: 999px;\n  padding: 10px 22px;\n  font-weight: 600;\n  border: 1px solid transparent;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  transition: transform 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;\n}\n\n.drive-page .components-button.is-primary {\n  background: #1d4ed8;\n  color: #ffffff;\n  box-shadow: 0 10px 24px rgba(37, 99, 235, 0.25);\n}\n\n.drive-page .components-button.is-primary:hover:not(:disabled),\n.drive-page .components-button.is-primary:focus-visible {\n  background: #1e40af;\n  box-shadow: 0 14px 30px rgba(37, 99, 235, 0.3);\n}\n\n.drive-page .components-button.is-secondary {\n  background: #f1f5f9;\n  color: #1f2937;\n  border-color: #d0d7e2;\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);\n}\n\n.drive-page .components-button.is-secondary:hover:not(:disabled),\n.drive-page .components-button.is-secondary:focus-visible {\n  background: #e2e8f0;\n  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.15);\n}\n\n.drive-page .drive-toggle-button {\n  background: #ffffff;\n  color: #1d4ed8;\n  border-color: rgba(37, 99, 235, 0.35);\n  box-shadow: 0 8px 20px rgba(37, 99, 235, 0.18);\n}\n\n.drive-page .drive-toggle-button:hover:not(:disabled),\n.drive-page .drive-toggle-button:focus-visible {\n  background: #f8fafc;\n  color: #1e40af;\n  border